// Short concept cards: each explains a term in plain language and why it changes the mission.
// They are opened from the "?" buttons next to resources, so ideas arrive when the player needs them.
export const LEARN = {
  altitude: {title: 'Orbital altitude', simple: 'How high the spacecraft flies above the surface. Lower is closer to the ground; higher takes longer to go around.', why: 'Lower orbits give sharper pictures but circle faster, so the Sun, shadow and ground contact all come around more often. Higher orbits see more at once with less detail.', tryThis: 'Move the altitude slider and watch the orbit period and the science quality change.'},
  inclination: {title: 'Orbit inclination', simple: 'The tilt of the orbit. 0° circles the equator; 90° passes over the poles.', why: 'Polar targets can only be seen from a near-polar orbit. Launch vehicles also differ in which tilts they can reach.', tryThis: 'Choose 30° and read the launch compatibility check.'},
  eclipse: {title: 'Eclipse', simple: 'The part of each orbit spent in the planet’s shadow, with no sunlight for the solar panels.', why: 'In shadow the spacecraft runs on its battery alone. A big array does not help if the battery is too small for the dark part of the orbit.', tryThis: 'Compare the eclipse reserve for the compact and endurance power kits.'},
  contact: {title: 'Ground contact', simple: 'The short window each orbit when the antenna can talk to Earth.', why: 'Data can only be sent during contact, which is open for about a fifth of the time here. Between contacts the recorder has to hold everything the instrument collects.', tryThis: 'Look at the recorder warning: it compares fill time with the time to the first contact.'},
  datarate: {title: 'Data rate', simple: 'How many megabits per second the instrument produces or the antenna sends.', why: 'A sharper instrument makes more data. If the link and recorder cannot keep up, observations are discarded and never reach the scientists.', tryThis: 'Swap the survey camera for the polar imager and watch the contact margin.'},
  power: {title: 'Power and energy', simple: 'Power (watts) is the rate of using electricity. Energy (watt-hours) is the amount stored in the battery.', why: 'Panels deliver power only in sunlight. The battery must store enough energy to carry the loads through shadow.', tryThis: 'Raise instrument duty and see peak power and eclipse reserve change.'},
  mass: {title: 'Mass and launch capacity', simple: 'Every kilogram counts: the launch vehicle can only throw a limited mass to the target orbit.', why: 'Fuel, instruments and batteries share the same limit. More fuel means a lighter instrument, and the other way round.', tryThis: 'Add propellant until the mass margin turns red.'},
  deltav: {title: 'Delta-v', simple: 'How much the spacecraft can change its speed with its fuel. It is a budget for maneuvers, not a speed.', why: 'Getting captured into orbit uses most of it. Too little leaves no reserve for problems.', tryThis: 'Switch to the efficient thruster and compare the maneuver reserve.'},
  budget: {title: 'Budget', simple: 'The credits available to build and operate the mission.', why: 'A better part usually costs more. There is rarely a single best design, only a good one for your objective.', tryThis: 'Find two different designs that both fit the budget and meet the objective.'},
  schedule: {title: 'Development schedule', simple: 'How many months the team needs to build and test the spacecraft before the launch window.', why: 'Parts are built in parallel, so the slowest part sets the pace, and every extra part adds integration and test time.', tryThis: 'Pick the expanded recorder and the precision bus and watch the months.'},
  launch: {title: 'Launch vehicle envelope', simple: 'Each launch vehicle can reach certain orbits and carry a limited mass.', why: 'A shared ride is cheap but limited. A dedicated launch costs more and goes almost anywhere.', tryThis: 'Choose a low-inclination orbit and see which vehicle can fly it.'},
  margin: {title: 'Margins', simple: 'The spare capacity left over after a design meets its needs.', why: 'Real missions keep reserves because something always goes wrong. A zero margin works on paper and fails in flight.', tryThis: 'Compare how a thin margin and a healthy margin behave in the same crisis.'},
  weather: {title: 'Space weather and dust', simple: 'Energetic particles and dust storms are part of the environment spacecraft fly in.', why: 'Particles add noise to measurements; dust blocks sunlight. Whether you keep observing or protect the instruments depends on your margins.', tryThis: 'Fly the Lunar Ice Hunter or Mars Dust Season scenario.'}
};
